id":"via.core_mastery.03","text":"Am valued by my friends for my good judgment.","required":true},{"id":"via.core_mastery.04","text":"Do not stand up for my beliefs.","required":true},{"id":"via.core_mastery.05","text":"Have trouble guessing how others will react.","required":true},{"id":"via.core_mastery.06","text":"Have difficulty getting others to work together.","required":true}],"optionalContext":[],"suggestedRepeatDays":null,"contentHash":"sha256:b2b1a5bdf4649343e8facf439ee103de3f8e359aeaed39b85f881ae115050ecd"}]
$hh_via_r$::jsonb) loop
  if exists (select 1 from app.assessment_versions where id=(d->>'id')::uuid and content_hash<>d->>'contentHash') then
    raise exception 'Conflicting VIA-R instrument ID %',d->>'id';
  end if;
  if exists (select 1 from app.assessment_versions where definition_key=d->>'key' and definition_version=d->>'version' and instrument_locale=d->>'instrumentLocale' and content_hash<>d->>'contentHash') then
    raise exception 'Conflicting VIA-R definition %',d->>'key';
  end if;
  insert into app.assessment_versions (id,definition_key,definition_version,instrument_locale,translation_version,definition,questions,answer_schema,scoring_key,scoring_version,result_schema,timeframe,source_metadata,content_hash)
  values ((d->>'id')::uuid,d->>'key',d->>'version',d->>'instrumentLocale',d->>'translationVersion',d,d->'questions',jsonb_build_object('type','integer','minimum',(d->'answerScale'->>'min')::int,'maximum',(d->'answerScale'->>'max')::int),d->>'scoringKey',d->>'scoringVersion',jsonb_build_object('version',d->>'resultVersion'),d->>'timeframe',d->'source',d->>'contentHash')
  on conflict (id) do nothing;
 end loop;
end $$;
commit;
